{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is a Free Trial?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Free Trial is when a product is introduced in the market with all features accessible by potential users for a limited time-period at zero cost."
      }
    },
    {
      "@type": "Question",
      "name": "What is Freemium?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Freemium is when a product is introduced in the market with few features accessible by potential users for an unlimited time-period at zero cost."
      }
    }
  ]
}
</script>
"},"elements":[],"widgetType":"html"}],"isInner":false}]

