{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is design systems?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A design system is more than just components. It’s a shared language that bridges the gap between designers and developers."
      }
    },
    {
      "@type": "Question",
      "name": "Why Wrapper Components Matter?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Centralized Control: Wrapper components allow you to encapsulate common functionality or styles in one place, reducing duplication.\nReusability: By abstracting shared logic or behavior, they make it easier to use the same functionality across multiple components.\nExtensibility: Wrapper components enable easy customization without affecting the core component structure.\nAdherence to SOLID Principles: They align with SRP by ensuring that each component focuses on one responsibility, keeping logic modular and maintainable."
      }
    }
  ]
}
</script>
