    .slider-bg{
        background: #26252D;
          padding-top: 80px;
          padding-bottom: 160px;
          margin-top: 80px;
        }
    .slider-title{
        color: #ffffff;
          width: 100%;
          font-weight: normal !important;
        max-width: 1160px !important;
          margin-left: auto;
          margin-right: auto;
          padding-bottom: 40px;
        }
        .slider-container {
          margin-bottom: 40px;
          position: relative;
          display: flex;
          color: #ffffff;
        }

        .slider-label {
            margin-bottom: 0px;
            display: block;
            font-weight: normal;
            font-size: 14px;
            max-width: 120px;
            text-transform: uppercase;
            min-width: 120px;
            min-height: 40px;
        }
        .slider-main{
        width: 100%;
          max-width: 1160px;
          margin-left: auto;
          margin-right: auto;
          padding-left: 0;
          padding-right: 0;
          position: static;
          justify-content: space-between;
         }

        .slider-main input[type="range"] {
          -webkit-appearance: none;
          width: 100%;
          height: 8px;
          border-radius: 5px;
          background: linear-gradient(to right, rgba(118, 116, 255, 1), rgba(118, 116, 255, 0.6) 0% 0% / 100% 100% no-repeat, #585863B2);
          outline: none;
          opacity: 0.9;
          transition: opacity 0.2s, background 0.2s;
        }

        .slider-main input[type="range"]:hover {
          opacity: 1;
        }

        .slider-main input[type="range"]::-webkit-slider-thumb {
          -webkit-appearance: none;
          appearance: none;
          width: 20px;
          height: 20px;
          border-radius: 50%;
          background: rgba(118, 116, 255, 1);
          border: 2px solid rgba(118, 116, 255, 1);
          cursor: pointer;
          transition: background 0.2s;
          z-index: 999;
        }

        .slider-main input[type="range"]::-webkit-slider-thumb:hover {
          background: rgba(118, 120, 255, 1);
        }

        .slider-main input[type="range"]::-moz-range-thumb,
        .slider-main input[type="range"]::-ms-thumb {
          width: 20px;
          height: 20px;
          border-radius: 50%;
          background: rgba(118, 116, 255, 1);
          border: 2px solid rgba(118, 116, 255, 1);
          cursor: pointer;
        }

        .slider-markers {
            position: absolute;
            top: 1px;
            left: 120px;
            right: 0;
            display: flex;
            justify-content: space-between;
            pointer-events: none;
        }

        .slider-markers .marker {
          width: 6px;
          height: 6px;
          background: rgba(32, 31, 39, 1);
          border-radius: 50%;
          position: relative;
        }

        .value-display {
          margin-top: 5px;
          font-size: 14px;
        }

        .image-container {
          text-align: center;
        }

        .image-container img {
          width: 300px;
          height: auto;
          border-radius: 8px;
        }
        #sliders{
            width: 70%;
            padding-top: 60px;
        }
        .image-container{
            width: 25%;
        }
        .slider-main{
            display: flex;
            width: 100%;
            width: 100%;
            align-items: stretch;
        }
        .header-hero{
            margin: 0px;
            max-width: 100%;
            padding-bottom: 0px;
        }
        .wrapper-legal-page {
            margin: 0px;
            max-width: 100%;
        }
        .author-wrapper {
            grid-column-gap: 4px;
            grid-row-gap: 4px;
            margin-bottom: 30px;
            margin-left: auto;
            margin-right: auto;
            max-width: 940px;
        }
        .main-rt p, .main-rt h1, .main-rt h2, .main-rt h3, .main-rt figure {
            max-width: 940px;
            margin-left: auto;
            margin-right: auto;
        }
        .w-richtext figure.w-richtext-align-fullwidth {
            text-align: center;
            clear: both;
            width: 100%;
            max-width: 1160px;
            margin-left: auto;
            margin-right: auto;
            display: block;
            margin-top: 180px;
        }
        .header-hero.footer {
          width: 100%;
          max-width: 1520px;
          margin-left: auto;
          margin-right: auto;
          padding-left: 0;
          padding-right: 0;
          position: static;
        }
        .marker-label {
          color: white;
          font-size: 12px;
          position: absolute;
          top: 20px;
          white-space: nowrap;
          opacity: 0.6;
        }
        .image-container img {
      width: 300px;
      height: auto;
      transition: opacity 0.5s ease-in-out;
      opacity: 1;
      left: 0;
      filter: drop-shadow(2px 4px 6px black);
    }

    .image-container {
      position: relative;
      width: 300px;
      height: auto;
      border-radius: 8px;
    }

    .image-container img {
      width: 100%;
      height: auto;
      transition: transform 0.5s ease, opacity 0.5s ease;
    }

    /* Slide out to left */
    .slide-left {
      transform: translateX(-100%);
      opacity: 0;
    }

    /* Slide in from right */
    .slide-in {
      transform: translateX(100%);
      opacity: 0;
      animation: slideIn 0.5s forwards;
    }

    @keyframes slideIn {
      from {
        transform: translateX(100%);
        opacity: 0;
      }
      to {
        transform: translateX(0);
        opacity: 1;
      }
    }

    .card {
      position: absolute;
      top: 0;
      left: 0;
      z-index: 2;
      transform: translateY(0) rotate(4deg) translateX(25px) scale(1);
      transform-origin: 0 0;
      padding: 0px !important;
      transition: transform 0.6s cubic-bezier(0.8, 0.2, 0.1, 0.8) 0.1s, background 0.4s linear;
      :last-child {
        margin-bottom: 0;
      }
    }

    .card--next {
      z-index: 5;
      transform: translateY(-25px) rotate(4deg) translateX(25px) scale(1);
    }

    .card--out {
      animation: card-out 0.6s cubic-bezier(0.8, 0.2, 0.1, 0.8);
      transform: translateY(-50px) rotate(8deg) translateX(55px) scale(0.95);
      z-index: 1;
      background: #bbb;
    }
    .card--current {
      cursor: auto;
      user-select: auto;
      position: relative;
      z-index: 10;
      opacity: 1;
      transform: rotate(-1deg) translateX(0%) scale(1);
    }
    .card-blur{
      opacity: 0.9 !important;
      filter: blur(1px) !important;
    }
    @media only screen and (min-width: 240px) and (max-width: 479px) {
    	.slider-bg {
      margin-left: -20px !important;
           margin-right: -20px !important;
      padding-left: 20px !important;
           padding-right: 20px !important;
      padding-bottom: 60px !important; 
    }
    .slider-main{
        flex-direction: column-reverse !important;
    }
    #sliders{
        width: 100% !important;
      padding-top: 0px !important;
    }
    .slider-container{
        flex-direction: column !important;
    }
    .image-container{
        min-height: 350px !important;
      margin: 60px auto 0px auto !important;
      width: 65% !important;
    }
    .slider-label{
        max-width: 100% !important;
      margin-top: 20px !important;
    }
    .slider-markers{
        top: 61px !important;
      left: 0 !important;
    }
    .slider-title{
        padding-bottom: 0px !important;
    }
    .header-hero.footer{
    	padding-left: 20px;
      padding-right: 20px;
    }
    }

    @keyframes card-out {
      0% {
        z-index: 20;
        transform: translateY(0px) rotate(15deg);
      }
      50% {
        transform: translateY(-120%) rotate(25deg) translateX(-40px);
      }
      80% {
        z-index: 1;
      }
      100% {
        transform: translateY(-50px) rotate(8deg) translateX(55px) scale(0.95);
      }
    }

      </style>
    <div class="slider-bg">
    <h2 class="slider-title">
    Find Your Fit:<br>UI Kit vs. Custom Components
    </h2>
    <div class="slider-main">
      <div id="sliders"><div class="slider-container"><label class="slider-label">Speed:</label><input type="range" min="0" max="4" step="1" data-index="0" style="background: linear-gradient(to right, rgb(118, 116, 255), rgba(118, 116, 255, 0.6) 0%, rgba(88, 88, 99, 0.698) 0%);"><div class="slider-markers"><div class="marker"><div class="marker-label" style="left: 0%;">Slow</div></div><div class="marker"></div><div class="marker"></div><div class="marker"></div><div class="marker"><div class="marker-label" style="left: auto; right: 0px;">Fast</div></div></div></div><div class="slider-container"><label class="slider-label">Flexibility:</label><input type="range" min="0" max="4" step="1" data-index="1" style="background: linear-gradient(to right, rgb(118, 116, 255), rgba(118, 116, 255, 0.6) 0%, rgba(88, 88, 99, 0.698) 0%);"><div class="slider-markers"><div class="marker"><div class="marker-label" style="left: 0%;">Standard</div></div><div class="marker"></div><div class="marker"></div><div class="marker"></div><div class="marker"><div class="marker-label" style="left: auto; right: 0px;">Unique</div></div></div></div><div class="slider-container"><label class="slider-label">Brand Uniqueness:</label><input type="range" min="0" max="4" step="1" data-index="2" style="background: linear-gradient(to right, rgb(118, 116, 255), rgba(118, 116, 255, 0.6) 0%, rgba(88, 88, 99, 0.698) 0%);"><div class="slider-markers"><div class="marker"><div class="marker-label" style="left: 0%;">Standard</div></div><div class="marker"></div><div class="marker"></div><div class="marker"></div><div class="marker"><div class="marker-label" style="left: auto; right: 0px;">Adaptable</div></div></div></div><div class="slider-container"><label class="slider-label">Maintenance Effort:</label><input type="range" min="0" max="4" step="1" data-index="3" style="background: linear-gradient(to right, rgb(118, 116, 255), rgba(118, 116, 255, 0.6) 0%, rgba(88, 88, 99, 0.698) 0%);"><div class="slider-markers"><div class="marker"><div class="marker-label" style="left: 0%;">Low</div></div><div class="marker"></div><div class="marker"></div><div class="marker"></div><div class="marker"><div class="marker-label" style="left: auto; right: 0px;">High</div></div></div></div><div class="slider-container"><label class="slider-label">Accessibility Level:</label><input type="range" min="0" max="2" step="1" data-index="4" style="background: linear-gradient(to right, rgb(118, 116, 255), rgba(118, 116, 255, 0.6) 0%, rgba(88, 88, 99, 0.698) 0%);"><div class="slider-markers"><div class="marker"><div class="marker-label" style="left: 0%;">A</div></div><div class="marker"><div class="marker-label" style="left: 50%;">AA</div></div><div class="marker"><div class="marker-label" style="left: auto; right: 0px;">AAA</div></div></div></div></div>
      <div class="image-container" style="position:relative;">
        <img id="dynamicImagebg1" style="position:absolute" class="image card" src="https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png" alt="Dynamic Image">
        <img id="dynamicImagebg2" style="position:absolute" class="image card--next" src="https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png" alt="Dynamic Image">
        <img id="dynamicImage" style="position:absolute" class="image card--current" src="https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png" alt="Dynamic Image">
      </div>
    </div>
    </div>

   <script>
  // Clear the sliders container before creating new sliders
  const slidersContainer = document.getElementById('sliders');
  slidersContainer.innerHTML = '';

  const sliderLabels = ["Speed", "Flexibility", "Brand Uniqueness", "Maintenance Effort", "Accessibility Level"];
  const markerLabels = [
    ["Slow","","","", "Fast"],
    ["Standard","","","", "Unique"],
    ["Standard","","","", "Adaptable"],
    ["Low","","","", "High"],
    ["A", "AA", "AAA"]
  ];

  const min = 0;
  const max = 4;
  const step = 1;

  const imageElement = document.getElementById('dynamicImage');
  const imageElementbg1 = document.getElementById('dynamicImagebg1');
  const imageElementbg2 = document.getElementById('dynamicImagebg2');

  const sliderValues = [];

  for (let i = 0; i < sliderLabels.length; i++) {
    const sliderContainer = document.createElement('div');
    sliderContainer.className = 'slider-container';

    const label = document.createElement('label');
    label.className = 'slider-label';
    label.textContent = `${sliderLabels[i]}:`;

    const slider = document.createElement('input');
    slider.type = 'range';

    if (i === sliderLabels.length - 1) {
      slider.min = 0;
      slider.max = 2;
      slider.step = 1;
    } else {
      slider.min = min;
      slider.max = max;
      slider.step = step;
    }

    slider.value = slider.min;
    slider.dataset.index = i;

    const valueDisplay = document.createElement('div');
    valueDisplay.className = 'value-display';
    valueDisplay.textContent = `Value: ${slider.value}`;

    const markersContainer = document.createElement('div');
    markersContainer.className = 'slider-markers';
    const totalSteps = (slider.max - slider.min) / slider.step;

    for (let j = 0; j <= totalSteps; j++) {
      const marker = document.createElement('div');
      marker.className = 'marker';
      markersContainer.appendChild(marker);

      // Add marker labels
      if (i < markerLabels.length) {
        const markerLabel = markerLabels[i][j];
        if (markerLabel) {
          const labelElement = document.createElement('div');
          labelElement.className = 'marker-label';
          labelElement.textContent = markerLabel;
          labelElement.style.left = `${(j / totalSteps) * 100}%`;
          if (j === totalSteps) {
            labelElement.style.left = "auto";
            labelElement.style.right = "0";
          }
          marker.appendChild(labelElement);
        }
      }
    }

    const updateSliderBackground = (sliderElement) => {
      const percentage = ((sliderElement.value - sliderElement.min) / (sliderElement.max - sliderElement.min)) * 100;
      sliderElement.style.background = `linear-gradient(to right, rgba(118, 116, 255, 1), rgba(118, 116, 255, 0.6) ${percentage}%, #585863B2 ${percentage}%)`;
    };

    updateSliderBackground(slider);

    slider.addEventListener('input', (event) => {
      const index = event.target.dataset.index;
      sliderValues[index] = parseInt(event.target.value);
      valueDisplay.textContent = `Value: ${event.target.value}`;
      updateSliderBackground(slider);
      updateImage();
    });

    sliderContainer.appendChild(label);
    sliderContainer.appendChild(slider);
    sliderContainer.appendChild(markersContainer);
    sliderContainer.appendChild(valueDisplay);

    slidersContainer.appendChild(sliderContainer);

    sliderValues.push(parseInt(slider.value));
  }

  const updateImage = () => {
    const speed = sliderValues[0];
    const flexibility = sliderValues[1];
    const brandUniqueness = sliderValues[2];
    const maintenanceEffort = sliderValues[3];
    const accessibility = sliderValues[4];

    let newSrc = "";
    if(speed + flexibility <= 1 && accessibility < 1 && brandUniqueness + maintenanceEffort <= 1){
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png"
    } else if (speed + flexibility <= brandUniqueness + maintenanceEffort && brandUniqueness + maintenanceEffort < 3) {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/uikit.png";
    } else if (speed + flexibility < brandUniqueness + maintenanceEffort && brandUniqueness + maintenanceEffort < 5) {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png";
    } else if (speed + flexibility < brandUniqueness + maintenanceEffort && brandUniqueness + maintenanceEffort > 5) {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/hybrid.png";
    } else if (maintenanceEffort + brandUniqueness < 3) {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/uikit.png";
    } else if (accessibility > 1) {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/hybrid.png";
    } else {
      newSrc = "https://www.copods.co/wp-content/uploads/2025/06/captain-custom.png"
    }

    if (imageElement.src !== newSrc) {
      imageElementbg1.classList.add("card-blur");
      imageElementbg2.classList.add("card-blur");
      imageElement.classList.add("card--out");

      setTimeout(function(){ 
        imageElement.classList.add("card-blur");
        imageElement.src = newSrc;
      }, 200);

      setTimeout(function(){ 
        imageElementbg1.src = newSrc;
        imageElementbg2.src = newSrc;
      }, 400);

      setTimeout(function(){ 
        imageElement.classList.remove("card--out");
        imageElement.classList.remove("card-blur");
        imageElementbg1.classList.remove("card-blur");
        imageElementbg2.classList.remove("card-blur");
      }, 500);
    }
  };
</script>
